const { app, BrowserWindow, protocol, session, nativeTheme } = require("electron");
const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");
const http = require("node:http");
const { once } = require("node:events");
const { registerChatWorkPanelLocalFileProtocolScheme } = require("../../src/main/modules/work-panel/local-files.ts");
const { renderLocalMarkdownAsync } = require("../../src/main/modules/work-panel/local-document-render.ts");
const { createWorkspaceHost, until, pause } = require("./local-document-workspace-host.cjs");
const root = process.env.LOCAL_DOCUMENT_TEST_ROOT;
app.setPath("userData", path.join(root, "profile"));
app.setPath("sessionData", path.join(root, "session"));
registerChatWorkPanelLocalFileProtocolScheme(protocol);
app.on("window-all-closed", () => {});
let server;
let host;
let abortedRender = false;
let slowRenderStarted = false;

async function run() {
  await app.whenReady();
  nativeTheme.themeSource = "light";
  const requests = [];
  server = http.createServer((request, response) => {
    requests.push(request.headers.cookie || "");
    response.setHeader("Content-Type", "text/javascript");
    response.end("window.externalScriptLoaded = true");
  });
  server.listen(0, "127.0.0.1");
  await once(server, "listening");
  const external = `http://127.0.0.1:${server.address().port}`;
  await session.defaultSession.cookies.set({ url: external, name: "host-secret", value: "not-shared" });
  const files = path.join(root, "documents");
  fs.mkdirSync(files);
  const markdown = path.join(files, " 中文 % #说明.MD");
  const html = path.join(files, "交互 页面.html");
  fs.writeFileSync(path.join(files, "image.svg"), '<svg xmlns="http://www.w3.org/2000/svg" width="240" height="70"><rect width="240" height="70" fill="#e5efff"/></svg>');
  fs.writeFileSync(markdown, "# 中文 Markdown 预览\n\n任意本地文件，无需先创建聊天。\n\n| 类型 | 状态 |\n| --- | --- |\n| Markdown | 已渲染 |\n| HTML | 主窗口标签 |\n\n- [x] 中文与空格文件名\n\n```js\nconst hello = '你好';\n```\n\n![示例](image.svg)\n\n<script>window.untrustedRan = true</script>\n");
  fs.writeFileSync(path.join(files, "style.css"), "body{font:18px system-ui;padding:40px}h1{color:rgb(12,34,56)}button{padding:12px 24px;font-size:16px}");
  fs.writeFileSync(path.join(files, "script.js"), "window.relativeScriptLoaded = true; window.firstScriptRtcType = typeof RTCPeerConnection; window.firstScriptTransportType = typeof WebTransport;");
  fs.writeFileSync(path.join(files, "worker.js"), "postMessage({rtc:typeof RTCPeerConnection,transport:typeof WebTransport,node:typeof process,ready:true})");
  fs.writeFileSync(html, `<!doctype html><meta charset="utf-8"><link rel="stylesheet" href="style.css"><h1>HTML 页面预览</h1><button onclick="this.textContent='已点击'">测试交互</button><input aria-label="草稿"><script src="script.js"></script><script src="${external}/test.js"></script>`);
  const outside = path.join(root, "private.txt");
  fs.writeFileSync(outside, "outside-secret");
  fs.symlinkSync(outside, path.join(files, "escape.txt"));
  host = await createWorkspaceHost(root, {
    renderMarkdown(bytes, fileName, signal) {
      if (fileName !== "slow.md") return renderLocalMarkdownAsync(bytes, fileName, signal);
      slowRenderStarted = true;
      return new Promise((_resolve, reject) => {
        signal.addEventListener("abort", () => { abortedRender = true; reject(new DOMException("Cancelled", "AbortError")); }, { once: true });
      });
    },
  });
  const { window, controller, snapshot, guestFor, activateDocument, invoke, openFile, startFileGroup, promoteFileGroup } = host;
  const originalMarkdown = fs.readFileSync(markdown);
  const originalHtml = fs.readFileSync(html);
  const originalFiles = fs.readdirSync(files).sort();
  await Promise.all([openFile(markdown), openFile(markdown), openFile(html)]);
  const state = await invoke("getState");
  let markdownItem = state.documents.find(item => item.kind === "markdown");
  let htmlItem = state.documents.find(item => item.kind === "html");
  assert.equal(state.documents.length, 2, "a repeated original activates the same draft tab");
  assert.equal(host.draftTargets.length, 1);
  assert.equal(host.promotedChats.length, 0, "no preview operation creates a server Chat identity");
  assert.equal(new Set(state.documents.map(item => item.documentId)).size, 2);
  assert.equal(new Set(state.documents.map(host.ownerKeyFor)).size, 1);
  assert.equal(new Set(state.documents.map(item => item.partition)).size, 2);
  assert.ok(state.documents.every(item => item.agentKey === "xiaojun" && item.ownerChatId === "" && /^[1-9]\d{12}$/.test(item.newChat)));
  assert.ok(host.routes.every(route => /^\/agent\/xiaojun\?newChat=[1-9]\d{12}$/.test(route)));
  const markdownGuest = await activateDocument(markdownItem.documentId);
  const htmlGuest = await activateDocument(htmlItem.documentId);
  const guardedRealms = await htmlGuest.executeJavaScript(`(async () => {
    const result = { firstScriptRtc: window.firstScriptRtcType, firstScriptTransport: window.firstScriptTransportType };
    const descriptor = Object.getOwnPropertyDescriptor(globalThis, 'RTCPeerConnection');
    result.immutable = descriptor.value === undefined && descriptor.configurable === false && descriptor.writable === false;
    const blank = document.createElement('iframe'); document.body.append(blank);
    result.blankImmediate = typeof blank.contentWindow.RTCPeerConnection;
    const child = document.createElement('iframe');
    child.srcdoc = '<p>local child</p>';
    const loaded = new Promise(resolve => child.onload = resolve); document.body.append(child); await loaded;
    result.srcdoc = typeof child.contentWindow.RTCPeerConnection;
    const sandbox = document.createElement('iframe'); sandbox.sandbox = 'allow-scripts';
    sandbox.srcdoc = '<script>parent.postMessage({localGuardCheck:true,rtc:typeof RTCPeerConnection,transport:typeof WebTransport,node:typeof process,bridge:typeof electronAPI},"*")<\\/script>';
    const sandboxReady = new Promise((resolve, reject) => {
      const timer = setTimeout(() => reject(new Error('sandbox initialization timed out')), 4000);
      const handler = event => { if (event.source !== sandbox.contentWindow || !event.data.localGuardCheck) return;
        clearTimeout(timer); removeEventListener('message', handler); resolve(event.data); };
      addEventListener('message', handler);
    });
    document.body.append(sandbox); result.sandbox = await sandboxReady;
    const checkWorker = url => new Promise((resolve, reject) => {
      const worker = new Worker(url); const timer = setTimeout(() => { worker.terminate(); reject(new Error('worker initialization timed out')); }, 4000);
      worker.onmessage = event => { clearTimeout(timer); worker.terminate(); resolve(event.data); };
      worker.onerror = () => { clearTimeout(timer); worker.terminate(); reject(new Error('worker failed')); };
    });
    result.worker = await checkWorker(new URL('worker.js', location.href).href);
    const blobUrl = URL.createObjectURL(new Blob(['postMessage({rtc:typeof RTCPeerConnection,transport:typeof WebTransport,node:typeof process,ready:true})'], {type:'text/javascript'}));
    result.blobWorker = await checkWorker(blobUrl); URL.revokeObjectURL(blobUrl);
    blank.remove(); child.remove(); sandbox.remove(); return result;
  })()`);
  console.log("Local document protected realms:", JSON.stringify(guardedRealms));
  assert.equal(guardedRealms.firstScriptRtc, "undefined", "the first document script must already be protected");
  assert.equal(guardedRealms.firstScriptTransport, "undefined");
  assert.equal(guardedRealms.immutable, true);
  assert.equal(guardedRealms.blankImmediate, "undefined");
  assert.equal(guardedRealms.srcdoc, "undefined");
  assert.equal(guardedRealms.sandbox.rtc, "undefined");
  assert.equal(guardedRealms.sandbox.transport, "undefined");
  assert.equal(guardedRealms.sandbox.node, "undefined");
  assert.equal(guardedRealms.sandbox.bridge, "undefined");
  for (const worker of [guardedRealms.worker, guardedRealms.blobWorker]) {
    assert.deepEqual(worker, {rtc:"undefined",transport:"undefined",node:"undefined",ready:true});
  }
  assert.equal((await snapshot()).guests.length, 2);
  assert.ok(state.documents.every(item => !JSON.stringify(item).includes(files)), "renderer receives opaque URLs, never paths");
  for (const item of [markdownItem, htmlItem]) {
    assert.equal(host.sourcePathFor(item), fs.realpathSync(item.kind === "markdown" ? markdown : html), "Main retains the original selection without a copy or prompt");
    await assert.rejects(controller.resolveActiveFile({chatId: "", agentKey: item.agentKey, documentId: item.documentId}));
  }
  await promoteFileGroup();
  const firstPromotion = await invoke("getState");
  markdownItem = firstPromotion.documents.find(item => item.documentId === markdownItem.documentId);
  htmlItem = firstPromotion.documents.find(item => item.documentId === htmlItem.documentId);
  assert.equal((await guestFor(markdownItem.documentId)).id, markdownGuest.id);
  assert.equal((await guestFor(htmlItem.documentId)).id, htmlGuest.id, "canonical promotion preserves the existing guest");
  assert.equal(host.promotedChats.length, 1);
  assert.equal((await controller.resolveActiveFile({chatId: htmlItem.ownerChatId, agentKey: htmlItem.agentKey, documentId: htmlItem.documentId})).path, fs.realpathSync(html));
  await startFileGroup();
  const repeatedDraft = await openFile(markdown);
  assert.equal(repeatedDraft.ownerChatId, "");
  assert.equal(host.promotedChats.length, 1, "the second draft group also stays local before its first query");
  const repeatedMarkdownGuest = await activateDocument(repeatedDraft.documentId);
  await promoteFileGroup();
  const repeatedMarkdownItem = (await invoke("getState")).documents.find(item => item.documentId === repeatedDraft.documentId);
  assert.notEqual(markdownItem.ownerChatId, repeatedMarkdownItem.ownerChatId);
  assert.notEqual(markdownGuest.id, repeatedMarkdownGuest.id);
  assert.equal(BrowserWindow.getAllWindows().length, 1, "all file groups share the existing main window");
  assert.equal((await snapshot()).guests.length, 3);
  assert.deepEqual(fs.readdirSync(files).sort(), originalFiles);
  assert.deepEqual(fs.readFileSync(markdown), originalMarkdown);
  assert.deepEqual(fs.readFileSync(html), originalHtml);
  assert.equal(await markdownGuest.executeJavaScript("document.querySelector('h1').textContent"), "中文 Markdown 预览");
  assert.equal(await repeatedMarkdownGuest.executeJavaScript("document.querySelector('h1').textContent"), "中文 Markdown 预览");
  assert.equal(await markdownGuest.executeJavaScript("document.querySelectorAll('table tbody tr').length"), 2);
  assert.equal(await markdownGuest.executeJavaScript("document.querySelector('pre code').textContent.includes('你好')"), true);
  assert.equal(await markdownGuest.executeJavaScript("typeof window.untrustedRan"), "undefined");
  await until(() => markdownGuest.executeJavaScript("document.images[0].complete && document.images[0].naturalWidth === 240"), "relative Markdown image");
  assert.equal(await htmlGuest.executeJavaScript("window.relativeScriptLoaded"), true);
  assert.equal(await htmlGuest.executeJavaScript("typeof window.externalScriptLoaded"), "undefined");
  assert.equal(await htmlGuest.executeJavaScript("getComputedStyle(document.querySelector('h1')).color"), "rgb(12, 34, 56)");
  await htmlGuest.executeJavaScript("document.querySelector('button').click(); document.querySelector('input').value = '未提交草稿'");
  await activateDocument(markdownItem.documentId);
  await window.webContents.executeJavaScript("window.setWorkspaceVisible(false)");
  await pause(80);
  await window.webContents.executeJavaScript("window.setWorkspaceVisible(true)");
  await activateDocument(htmlItem.documentId);
  assert.equal((await guestFor(htmlItem.documentId)).id, htmlGuest.id, "Chat and route visibility changes preserve the existing guest");
  assert.deepEqual(await htmlGuest.executeJavaScript("[document.querySelector('button').textContent, document.querySelector('input').value]"), ["已点击", "未提交草稿"]);
  const initialIds = new Set(state.documents.map(item => item.documentId));
  await activateDocument(repeatedMarkdownItem.documentId);
  await openFile(html);
  const reopenedState = await invoke("getState");
  const reopenedHtmlItem = reopenedState.documents.find(item => item.kind === "html" && !initialIds.has(item.documentId));
  const reopenedHtmlGuest = await activateDocument(reopenedHtmlItem.documentId);
  assert.equal(reopenedState.documents.length, 4);
  assert.equal(host.draftTargets.length, 2);
  assert.equal(host.promotedChats.length, 2);
  assert.notEqual(reopenedHtmlItem.ownerChatId, htmlItem.ownerChatId, "the same original in different file groups retains independent ownership");
  assert.notEqual(reopenedHtmlItem.documentId, htmlItem.documentId);
  assert.notEqual(reopenedHtmlItem.partition, htmlItem.partition);
  assert.notEqual(reopenedHtmlGuest.id, htmlGuest.id);
  assert.equal(reopenedState.activeDocumentId, reopenedHtmlItem.documentId);
  assert.deepEqual(await reopenedHtmlGuest.executeJavaScript("[document.querySelector('button').textContent, document.querySelector('input').value]"), ["测试交互", ""]);
  assert.deepEqual(await htmlGuest.executeJavaScript("[document.querySelector('button').textContent, document.querySelector('input').value]"), ["已点击", "未提交草稿"], "the old Chat document is retained with its own page state");
  await assert.rejects(controller.resolveActiveFile({chatId: reopenedHtmlItem.ownerChatId, agentKey: htmlItem.agentKey, documentId: htmlItem.documentId}), "another Chat cannot claim the first group's original");
  assert.equal((await controller.resolveActiveFile({chatId: reopenedHtmlItem.ownerChatId, agentKey: reopenedHtmlItem.agentKey, documentId: reopenedHtmlItem.documentId})).path, fs.realpathSync(html));
  assert.equal(requests.length, 0, "local HTML must not contact a remote server or leak host cookies");
  const allGuests = [markdownGuest, repeatedMarkdownGuest, htmlGuest, reopenedHtmlGuest];
  assert.equal(new Set(allGuests.map(guest => guest.session)).size, 4, "each Chat document has its own temporary session");
  for (const guest of allGuests) {
    assert.deepEqual(await guest.executeJavaScript("[typeof require, typeof process, typeof electronAPI, typeof workspace]"), ["undefined", "undefined", "undefined", "undefined"]);
    assert.notEqual(guest.session, session.defaultSession);
    assert.equal(guest.hostWebContents.id, window.webContents.id);
    assert.equal(guest.getLastWebPreferences().sandbox, true);
    assert.equal(guest.getLastWebPreferences().nodeIntegration, false);
    assert.equal(guest.getLastWebPreferences().nodeIntegrationInSubFrames, true);
  }
  assert.equal(await htmlGuest.executeJavaScript("fetch('escape.txt').then(r=>r.status)"), 404);
  assert.equal(await htmlGuest.executeJavaScript("fetch('../private.txt').then(r=>r.status)"), 404);
  assert.equal(await htmlGuest.executeJavaScript("fetch('file:///etc/passwd').then(()=>false,()=>true)"), true);
  assert.equal(await htmlGuest.executeJavaScript(`fetch(${JSON.stringify(markdownItem.url)}).then(r=>r.ok,()=>false)`), false);
  await htmlGuest.executeJavaScript("window.open('https://example.com')");
  assert.equal(BrowserWindow.getAllWindows().length, 1);
  const originalUrl = htmlGuest.getURL();
  await htmlGuest.executeJavaScript("location.href = 'https://example.com'");
  await pause(120);
  assert.equal(htmlGuest.getURL(), originalUrl);
  const atomicallySaved = path.join(files, "atomic-save.tmp");
  const openRevisionBeforeSave = (await invoke("getState")).openRevision;
  fs.writeFileSync(atomicallySaved, '<!doctype html><meta charset="utf-8"><h1>原文件已更新</h1>');
  fs.renameSync(atomicallySaved, html);
  for (const guest of [htmlGuest, reopenedHtmlGuest]) {
    await until(() => guest.executeJavaScript("document.querySelector('h1')?.textContent === '原文件已更新'").catch(() => false), "both Chats reload the same changed original");
  }
  assert.equal((await guestFor(htmlItem.documentId)).id, htmlGuest.id);
  assert.equal((await guestFor(reopenedHtmlItem.documentId)).id, reopenedHtmlGuest.id);
  assert.equal((await invoke("getState")).openRevision, openRevisionBeforeSave, "a file update is not a new open intent");
  assert.equal((await invoke("getState")).activeDocumentId, reopenedHtmlItem.documentId);
  const reopenedSession = reopenedHtmlGuest.session;
  const reopenedUrl = reopenedHtmlGuest.getURL();
  await invoke("close", reopenedHtmlItem.documentId);
  await until(() => reopenedHtmlGuest.isDestroyed(), "closing the new Chat file destroys only its guest");
  assert.equal(htmlGuest.isDestroyed(), false);
  assert.equal(await reopenedSession.fetch(reopenedUrl).then(() => false, () => true), true);
  fs.writeFileSync(html, '<!doctype html><meta charset="utf-8"><h1>旧对话仍然同步原件</h1>');
  await until(() => htmlGuest.executeJavaScript("document.querySelector('h1')?.textContent === '旧对话仍然同步原件'").catch(() => false), "closing one same-path document preserves the other's file watcher");
  assert.equal((await invoke("getState")).documents.length, 3);
  await window.webContents.executeJavaScript(`(() => { const view = document.createElement('webview'); view.partition = ${JSON.stringify(htmlItem.partition)}; view.src = ${JSON.stringify(htmlItem.url)}; document.body.append(view); })()`);
  await until(() => host.blockedAttachments.length === 1, "duplicate guest attach denied");
  assert.equal(htmlGuest.isDestroyed(), false);

  await activateDocument(markdownItem.documentId);
  window.setSize(390, 650);
  await pause(120);
  assert.equal(await markdownGuest.executeJavaScript("document.documentElement.scrollWidth <= innerWidth"), true);
  const modifiers = [process.platform === "darwin" ? "meta" : "control"];
  const shortcut = (guest, keyCode) => {
    guest.sendInputEvent({ type: "keyDown", keyCode, modifiers });
    guest.sendInputEvent({ type: "keyUp", keyCode, modifiers });
  };
  shortcut(markdownGuest, "F");
  await until(() => window.webContents.executeJavaScript(`window.lastBrowserShortcut?.guestId === ${markdownGuest.id} && window.lastBrowserShortcut.command === 'find'`), "find forwarded to trusted host");
  fs.writeFileSync(markdown, "# 刷新后的中文\n");
  shortcut(markdownGuest, "R");
  await until(() => markdownGuest.executeJavaScript("document.querySelector('h1')?.textContent === '刷新后的中文'").catch(() => false), "reload shortcut");
  await until(() => repeatedMarkdownGuest.executeJavaScript("document.querySelector('h1')?.textContent === '刷新后的中文'").catch(() => false), "the repeated Markdown Chat still observes its original");
  const oldSession = markdownGuest.session;
  const oldUrl = markdownGuest.getURL();
  shortcut(markdownGuest, "W");
  await until(() => markdownGuest.isDestroyed(), "close shortcut destroys only its guest");
  assert.equal(window.isDestroyed(), false);
  assert.equal((await invoke("getState")).documents.length, 2);
  assert.equal(repeatedMarkdownGuest.isDestroyed(), false);
  assert.equal(htmlGuest.isDestroyed(), false);
  assert.equal(await oldSession.fetch(oldUrl).then(() => false, () => true), true, "closed tab loses its protocol handler");
  const groupCountBeforeFailure = host.draftTargets.length;
  await assert.rejects(openFile(path.join(files, "missing.md")));
  assert.equal(host.draftTargets.length, groupCountBeforeFailure, "a missing file does not create a local group");
  const beforeRetry = new Set((await invoke("getState")).documents.map(item => item.documentId));
  await openFile(markdown);
  const retryItem = (await invoke("getState")).documents.find(item => !beforeRetry.has(item.documentId));
  const retryGuest = await activateDocument(retryItem.documentId);
  assert.notEqual(retryItem.ownerChatId, repeatedMarkdownItem.ownerChatId);
  assert.equal((await invoke("getState")).documents.length, 3, "a failed file must not prevent subsequent fresh opens");
  await htmlGuest.executeJavaScript("window.onbeforeunload = () => false; undefined");
  await invoke("close", htmlItem.documentId);
  await until(() => htmlGuest.isDestroyed(), "untrusted beforeunload cannot veto tab close");
  const slow = path.join(files, "slow.md");
  fs.writeFileSync(slow, "# slow");
  await openFile(slow);
  await until(() => slowRenderStarted, "in-flight Markdown render");
  const slowItem = (await invoke("getState")).documents.find(item => item.fileName === "slow.md");
  assert.equal(slowItem.ownerChatId, retryItem.ownerChatId, "a different file appends to the currently active file Chat");
  assert.equal(host.draftTargets.length, 2);
  assert.equal(host.promotedChats.length, 2);
  await invoke("close", slowItem.documentId);
  await until(() => abortedRender, "closing a tab aborts its active render");
  const survivors = [repeatedMarkdownGuest, retryGuest].map(guest => ({ guest, session: guest.session, url: guest.getURL() }));
  window.destroy();
  for (const survivor of survivors) {
    await until(() => survivor.guest.isDestroyed(), "main window destroys all retained Chat guests");
    assert.equal(await survivor.session.fetch(survivor.url).then(() => false, () => true), true, "main close revokes each surviving session");
  }
  controller.dispose();
  assert.equal(BrowserWindow.getAllWindows().length, 0);
  assert.equal(new Set(host.promotedChats.map(chat => chat.chatId)).size, 2);
  fs.writeFileSync(path.join(root, "passed.json"), JSON.stringify({ ok: true,
    counts: { initialConcurrentDocuments: 2, initialDraftGroups: 1, draftGroups: 2, promotedChats: 2, simultaneousMainWindows: 1, sameOriginalHtmlPreviews: 2 },
    checks: ["preview remains ownerless before first query", "same draft repeated original activates existing tab", "canonical promotion retains guests and sessions", "different file groups retain independent originals", "same original without copy or prompt", "old Chat page state retained", "one main window", "Markdown GFM", "Chinese paths", "HTML resources", "first script and synchronous blank network guard", "opaque child frame network guard without host APIs", "local and blob worker network guard", "tab and route state preservation", "isolated cookies", "no host bridge", "path escape denied", "popup/navigation denied", "same-original watch and independent close", "duplicate attach denied", "narrow layout", "find/reload/close", "render abort", "cleanup/reopen"] }));
  server.close();
  app.exit(0);
}
run().catch(error => { console.error(error); host?.dispose(); server?.close(); app.exit(1); });
